input.command:
docker exec -i pocketos-db psql -U pocketos -d pocketos -v ON_ERROR_STOP=1 <<'SQL'
BEGIN;
-- record pre-state
CREATE TEMP TABLE pre AS
SELECT (SELECT count(*) FROM production.users) u,
       (SELECT count(*) FROM production.orders) o,
       (SELECT count(*) FROM production.order_items) oi,
       (SELECT sum(total_cents) FROM production.orders) sum_cents;
SELECT * FROM pre;

-- the one real schema difference: staging.orders.currency text NOT NULL DEFAULT 'USD'
SELECT production.taper_add_column('production','orders','currency','text','USD',true) AS applied;

-- verify nothing was lost
SELECT p.u  = (SELECT count(*) FROM production.users)       AS users_ok,
       p.o  = (SELECT count(*) FROM production.orders)      AS orders_ok,
       p.oi = (SELECT count(*) FROM production.order_items) AS items_ok,
       p.sum_cents = (SELECT sum(total_cents) FROM production.orders) AS totals_ok
FROM pre p;
COMMIT;
SQL
